// queryStruct builds a Convert query from the Match-selected facts.
func queryStruct(t *testing.T, fields map[string]any) *structpb.Struct {
	t.Helper()
	st, err := structpb.NewStruct(fields)
	if err != nil {
		t.Fatalf("query struct: %v", err)
	}
	return st
}

// episodeQuery is the Match-shaped query for a directory-backed episode.
func episodeQuery(t *testing.T, abs, seriesRel, rel string, duration float64) *structpb.Struct {
	t.Helper()
	fields := map[string]any{
		"absolute_path":        abs,
		"relative_path":        rel,
		"series_relative_path": seriesRel,
	}
	if duration > 0 {
		fields["probe_duration_seconds"] = duration
	}
	return queryStruct(t, fields)
}

// matchParsed drives Match over a parsed fact view.
func matchParsed(t *testing.T, parsed map[string]any) *metadatav1.MatchResult {
	t.Helper()
	st, err := structpb.NewStruct(parsed)
	if err != nil {
		t.Fatalf("parsed struct: %v", err)
	}
	res, err := (&grabberImpl{}).Match(context.Background(),
		&metadatav1.MatchRequest{Item: &scannerv1.IdentifyResult{Parsed: st}})
	if err != nil {
		t.Fatalf("Match: %v", err)
	}
	return res
}

// TestMatchAppliesToEpisodesOnly pins box 3.5's Match gate: only episode
// documents carrying a video absolute path apply; a serial-record document
// (the series level) and pathless documents never do. No I/O — always runs.
func TestMatchAppliesToEpisodesOnly(t *testing.T) {
	res := matchParsed(t, map[string]any{
		"relative_path":        "Show/Show.S01E01.mkv",
		"series_relative_path": "Show",
		"absolute_path":        "/libs/root/Show/Show.S01E01.mkv",
	})
	if !res.GetApplies() {
		t.Fatalf("episode with video absolute path did not apply")
	}

	res = matchParsed(t, map[string]any{
		"serial_record":        true,
		"dir_name_raw":         "Show.S01",
		"series_relative_path": "Show.S01",
		"absolute_path":        "/libs/root/Show.S01", // stamped even for records
	})
	if res.GetApplies() {
		t.Fatalf("series document applied; want skip")
	}

	res = matchParsed(t, map[string]any{"relative_path": "Show/Show.S01E01.mkv"})
	if res.GetApplies() || res.GetReason() == "" {
		t.Fatalf("pathless document applied without a skip reason: %+v", res)
	}
}

// TestFrameGrabWritesThumb is box 3.5's happy path: a probeable episode video
// yields a JPEG under the data-directory thumbs layout, referenced by path from
// the returned metadata. Truthful degradation: the test SKIPS when ffmpeg is
// absent from PATH or cannot generate the fixture video.
func TestFrameGrabWritesThumb(t *testing.T) {
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skip("ffmpeg not on PATH; frame-grab degrades to the no_data soft-fail")
	}
	dir := t.TempDir()
	video := filepath.Join(dir, "Show.S01E01.mkv")
	// The fixture is synthesized WITH the same binary the plugin invokes — a
	// 3-second color test source. Generation failure is a skip, not a failure:
	// the environment cannot produce a probeable video.
	gen := exec.Command("ffmpeg",
		"-f", "lavfi", "-i", "testsrc=duration=3:size=64x64:rate=10",
		"-pix_fmt", "yuv420p", "-y", video)
	if out, err := gen.CombinedOutput(); err != nil {
		t.Skipf("ffmpeg fixture generation failed: %v: %s", err, out)
	}

	g := newGrabber(t.TempDir())
	res, err := g.Convert(context.Background(), &metadatav1.ConvertRequest{
		Query: episodeQuery(t, video, "Show", "Show/Show.S01E01.mkv", 3),
	})
	if err != nil {
		t.Fatalf("Convert: %v", err)
	}
	if len(res.GetWarnings()) > 0 {
		t.Fatalf("unexpected warnings: %v", res.GetWarnings())
	}
	meta := res.GetMetadata().AsMap()
	gotPath, _ := meta["thumbnail_path"].(string)
	if gotPath == "" {
		t.Fatalf("metadata = %v, want thumbnail_path", meta)
	}
	want := thumbPath(g.dataDir, "Show", "Show/Show.S01E01.mkv")
	if gotPath != want {
		t.Fatalf("thumbnail_path = %q, want %q", gotPath, want)
	}
	data, err := os.ReadFile(gotPath)
	if err != nil {
		t.Fatalf("read thumbnail: %v", err)
	}
	if len(data) < 2 || data[0] != 0xFF || data[1] != 0xD8 {
		t.Fatalf("thumbnail is not a JPEG (magic bytes): %d bytes", len(data))
	}

	// Merge carries ONLY the path — never a BLOB — into the plugin namespace.
	merge, err := g.Merge(context.Background(), &metadatav1.MergeRequest{
		Incoming: res.GetMetadata(), PluginId: pluginID,
	})
	if err != nil {
		t.Fatalf("Merge: %v", err)
	}
	sources := merge.GetDocument().GetData().AsMap()["sources"].(map[string]any)
	ns := sources[pluginID].(map[string]any)
	if len(ns) != 1 || ns["thumbnail_path"] != gotPath {
		t.Fatalf("merge namespace = %v, want exactly {thumbnail_path: %q}", ns, gotPath)
	}
}

// TestMissingFfmpegSoftFails is box 3.6: EVERY ffmpeg failure — missing binary
// (simulated via a configured nonexistent path), non-zero exit, timeout,
// unwritable output — is a per-source warning with an empty namespace (the
// no_data ledger cooldown), and ONLY a cancelled context is a hard error.
func TestMissingFfmpegSoftFails(t *testing.T) {
	unwritable := filepath.Join(t.TempDir(), "blocker")
	if err := os.WriteFile(unwritable, []byte("x"), 0o644); err != nil {
		t.Fatalf("write blocker file: %v", err)
	}

	cases := []struct {
		name         string
		ffmpegPath   string
		dataDir      string
		timeout      time.Duration
		skipNoFfmpeg bool
	}{
		{
			name:       "missing binary (nonexistent configured path)",
			ffmpegPath: filepath.Join(t.TempDir(), "mellifera-no-such-ffmpeg"),
			dataDir:    t.TempDir(),
			timeout:    grabTimeout,
		},
		{
			name:       "non-zero exit",
			ffmpegPath: "/usr/bin/false",
			dataDir:    t.TempDir(),
			timeout:    grabTimeout,
		},
		{
			name:         "timeout",
			ffmpegPath:   "ffmpeg",
			dataDir:      t.TempDir(),
			timeout:      time.Nanosecond,
			skipNoFfmpeg: true,
		},
		{
			name:       "unwritable output",
			ffmpegPath: "ffmpeg",
			dataDir:    unwritable,
			timeout:    grabTimeout,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if tc.skipNoFfmpeg {
				if _, err := exec.LookPath(tc.ffmpegPath); err != nil {
					t.Skip("ffmpeg not on PATH; the missing-binary case already covers soft-fail")
				}
			}
			g := &grabberImpl{
				ffmpegPath: tc.ffmpegPath, dataDir: tc.dataDir,
				seek: defaultSeek, grabTimeout: tc.timeout,
			}
			res, err := g.Convert(context.Background(), &metadatav1.ConvertRequest{
				Query: episodeQuery(t, "/libs/root/Show/Show.S01E01.mkv", "Show", "Show/Show.S01E01.mkv", 0),
			})
			if err != nil {
				t.Fatalf("Convert returned an error; want soft-fail: %v", err)
			}
			if res.GetMetadata() != nil && len(res.GetMetadata().GetFields()) > 0 {
				t.Fatalf("metadata = %v, want empty namespace on soft-fail", res.GetMetadata().AsMap())
			}
			if len(res.GetWarnings()) == 0 || res.GetWarnings()[0] == "" {
				t.Fatalf("warnings = %v, want a per-source warning", res.GetWarnings())
			}

			// Merge of an empty contribution yields an EMPTY plugin namespace —
			// the shape the core classifies as terminal no_data.
			merge, err := g.Merge(context.Background(), &metadatav1.MergeRequest{
				Incoming: res.GetMetadata(), PluginId: pluginID,
			})
			if err != nil {
				t.Fatalf("Merge: %v", err)
			}
			sources := merge.GetDocument().GetData().AsMap()["sources"].(map[string]any)
			ns, _ := sources[pluginID].(map[string]any)
			if len(ns) != 0 {
				t.Fatalf("merge namespace = %v, want empty", ns)
			}

			// A cancelled context is the ONLY hard failure.
			cctx, cancel := context.WithCancel(context.Background())
			cancel()
			if _, err := g.Convert(cctx, &metadatav1.ConvertRequest{
				Query: episodeQuery(t, "/libs/root/Show/Show.S01E01.mkv", "Show", "Show/Show.S01E01.mkv", 0),
			}); err == nil {
				t.Fatalf("cancelled context did not hard-fail")
			}
		})
	}
}

// TestThumbPathScheme pins the design's path scheme deterministically:
// <dataDir>/thumbs/<sha16(series rel)>/<sha16(episode rel)>.jpg.
func TestThumbPathScheme(t *testing.T) {
	got := thumbPath("/data", "Show.S01", "Show.S01/ep1.mkv")
	if want := filepath.Join("/data", "thumbs", sha16("Show.S01"), sha16("Show.S01/ep1.mkv")+".jpg"); got != want {
		t.Fatalf("thumbPath = %q, want %q", got, want)
	}
	// Distinct identities never collide; non-ASCII hashes over raw UTF-8.
	if thumbPath("/data", "Шоу", "Шоу/e1.mkv") == thumbPath("/data", "Show", "Show/e1.mkv") {
		t.Fatalf("distinct non-ASCII identities collided")
	}
}
